       result(sgetri_npvt_raw) &
       bind(C, name="rocsolver_sgetri_npvt")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: n
       type(c_ptr), value :: A
       integer(c_int), value :: lda
       type(c_ptr), value :: info
