       type(c_ptr), value :: n_sweeps
       type(c_ptr), value :: W
       integer(c_long), value :: strideW
       type(c_ptr), value :: info
       integer(c_int), value :: batch_count
       integer(c_int) :: chegvj_strided_batched_raw
    end function rocsolver_chegvj_strided_batched_raw

